 void seedCarmela(){db.execSQL("CREATE TABLE IF NOT EXISTS bundled_recipes(key TEXT PRIMARY KEY)");db.beginTransaction();try{try(Cursor c=db.rawQuery("SELECT key FROM bundled_recipes WHERE key=?",new String[]{"carmela-bolo-fuba-1"})){if(c.moveToFirst()){db.setTransactionSuccessful();return;}}ContentValues recipe=new ContentValues();recipe.put("name","Bolo de fubá");recipe.put("category","Doces");recipe.put("origin","carmela");recipe.put("time","");recipe.put("yield","");recipe.put("photo","");recipe.put("video","");recipe.put("step_photos","[]");recipe.put("ingredients","MASSA\n5 ovos\n1 xícara (chá) de manteiga derretida\n1 xícara (chá) de farinha de trigo\n2 xícaras (chá) de fubá\n2 xícaras (chá) de açúcar refinado\n1 xícara (chá) de leite\n1 xícara (chá) de leite de coco\n1 colher (sopa) de fermento em pó\nCOBERTURA\n2 xícaras (chá) de açúcar refinado\n1 xícara (chá) de leite de coco");recipe.put("steps","Bata as claras em neve.\nJunte as gemas, 2 xícaras de açúcar, a farinha de trigo, o fubá e o fermento.\nAlterne com 1 xícara de manteiga derretida, 1 xícara de leite e 1 xícara de leite de coco.\nCobertura: dissolva 2 xícaras de açúcar com 1 xícara de leite de coco.\nColoque a cobertura sobre o bolo ainda quente.");recipe.put("notes","Transcrita do caderno da Carmela. As 4 xícaras de açúcar foram separadas conforme o preparo: 2 na massa e 2 na cobertura. O leite comum aparece no preparo, mas não na lista original. O leite de coco da cobertura foi listado separadamente. O caderno não informa a etapa de assar, a temperatura, o tempo de forno nem o rendimento. Esses detalhes precisam ser confirmados antes do preparo. Ainda sem fotos do prato pronto ou das etapas.");db.insertOrThrow("recipes",null,recipe);db.execSQL("INSERT INTO bundled_recipes(key) VALUES(?)",new Object[]{"carmela-bolo-fuba-1"});db.setTransactionSuccessful();}finally{db.endTransaction();}}
