 @Override protected void onActivityResult(int request,int result,Intent data){super.onActivityResult(request,result,data);if(result!=RESULT_OK||data==null||data.getData()==null)return;final Uri uri=data.getData();final int selectedStep=pendingStep;mediaImporting=true;if(saveButton!=null)saveButton.setEnabled(false);Toast.makeText(this,"Guardando imagem…",Toast.LENGTH_SHORT).show();new Thread(()->{File dir=new File(getFilesDir(),"media");dir.mkdirs();File dest=new File(dir,UUID.randomUUID().toString());try(InputStream in=getContentResolver().openInputStream(uri);OutputStream out=new FileOutputStream(dest)){if(in==null)throw new IOException();byte[] buffer=new byte[65536];long total=0;int n;while((n=in.read(buffer))!=-1){total+=n;if(total>200L*1024*1024)throw new IOException("Escolha um arquivo de até 200 MB.");out.write(buffer,0,n);}runOnUiThread(()->{if(request==41){photo=dest.getAbsolutePath();if(photoLabel!=null)photoLabel.setText("📷  Foto adicionada · trocar");refreshPhoto();}else if(request==43&&selectedStep>=0&&selectedStep<stepPhotos.size()){stepPhotos.set(selectedStep,dest.getAbsolutePath());refreshStepEditor();}mediaImporting=false;if(saveButton!=null)saveButton.setEnabled(true);});}catch(Exception e){dest.delete();runOnUiThread(()->{mediaImporting=false;if(saveButton!=null)saveButton.setEnabled(true);Toast.makeText(this,e.getMessage()==null?"Não foi possível importar o arquivo.":e.getMessage(),Toast.LENGTH_LONG).show();});}}).start();}
 void save(){if(bookField.getSelectedItemPosition()==0){Toast.makeText(this,"Escolha o livro da receita.",Toast.LENGTH_LONG).show();scroll.smoothScrollTo(0,0);return;}for(EditText field:stepFields)if(field.getText().toString().trim().isEmpty()){field.setError("Descreva esta etapa ou remova o cartão.");field.requestFocus();return;}steps.setText(stepText());if(mediaImporting){Toast.makeText(this,"Aguarde o arquivo terminar de carregar.",Toast.LENGTH_SHORT).show();return;}for(EditText e:new EditText[]{name,ingredients,steps}){if(e.getText().toString().trim().isEmpty()){e.setError(e==name?"Qual é o nome da receita?":e==ingredients?"Adicione os ingredientes.":"Conte como preparar a receita.");(e==steps?stepFields.get(0):e).requestFocus();if(e==steps){stepFields.get(0).setError("Conte como preparar a receita.");return;}scroll.post(()->{android.graphics.Rect rect=new android.graphics.Rect();e.getDrawingRect(rect);body.offsetDescendantRectToMyCoords(e,rect);scroll.smoothScrollTo(0,Math.max(0,rect.top-d(25)));});return;}}ContentValues r=new ContentValues();r.put("collection",bookField.getSelectedItem().toString());r.put("origin","Livro da Carmela".equals(bookField.getSelectedItem().toString())?"carmela":"user");r.put("name",name.getText().toString().trim());r.put("category",categoryField.getSelectedItem().toString());r.put("time",time.getText().toString());r.put("yield",yield.getText().toString());r.put("ingredients",ingredients.getText().toString());r.put("steps",steps.getText().toString());r.put("notes",notes.getText().toString());r.put("photo",photo);r.put("video",video);r.put("step_photos",photoJson());try{long savedId;if(editing<0)savedId=db.insertOrThrow("recipes",null,r);else{db.update("recipes",r,"id=?",new String[]{String.valueOf(editing)});savedId=editing;}sync.changed(savedId);Toast.makeText(this,"Receita guardada com carinho.",Toast.LENGTH_SHORT).show();for(ContentValues saved:recipes())if(saved.getAsLong("id")==savedId){detail(saved);return;}home();}catch(Exception e){Toast.makeText(this,"Não foi possível salvar. Verifique o espaço do aparelho.",Toast.LENGTH_LONG).show();}}
 void confirmLeave(){if(mediaImporting){Toast.makeText(this,"Aguarde o arquivo terminar de carregar.",Toast.LENGTH_SHORT).show();return;}new AlertDialog.Builder(this).setTitle("Sair sem salvar?").setMessage("As alterações desta receita serão descartadas.").setNegativeButton("Continuar editando",null).setPositiveButton("Sair",(a,b)->home()).show();}
